import { readFileSync } from 'node:fs';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

async function main() {
  console.log('=== Step 1: self-sync GITHUB_TOKEN + GITHUB_REPO_URL from Render process.env → ownerVariablesStore ===');
  const syncRes = await fetch(`${API}/api/ivx/owner-variables/self-sync`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_TOKEN}` },
    body: JSON.stringify({
      names: ['GITHUB_TOKEN', 'GITHUB_REPO_URL'],
      overwriteExisting: true,
    }),
  });
  const syncText = await syncRes.text();
  console.log(`self-sync HTTP ${syncRes.status}: ${syncText.slice(0, 1200)}`);
  if (!syncRes.ok) { console.error('SELF-SYNC FAILED'); process.exit(1); }
  const sync = JSON.parse(syncText);
  console.log('\nsummary:', JSON.stringify(sync.summary, null, 2));
  console.log('results:', JSON.stringify(sync.results, null, 2));

  console.log('\n=== Step 2: verify status — both variables present in ownerVariablesStore ===');
  const statusRes = await fetch(`${API}/api/ivx/owner-variables/status`, {
    headers: { Authorization: `Bearer ${OWNER_TOKEN}` },
  });
  const statusText = await statusRes.text();
  console.log(`status HTTP ${statusRes.status}: ${statusText.slice(0, 1500)}`);
  if (!statusRes.ok) { console.error('STATUS FAILED'); process.exit(1); }
  const status = JSON.parse(statusText);
  const vars = status.variables || status.savedVariables || [];
  const githubToken = vars.find((v) => v.name === 'GITHUB_TOKEN');
  const githubRepo = vars.find((v) => v.name === 'GITHUB_REPO_URL');
  console.log('\nGITHUB_TOKEN in store:', githubToken ? `present (status=${githubToken.status}, masked=${githubToken.maskedPreview})` : 'MISSING');
  console.log('GITHUB_REPO_URL in store:', githubRepo ? `present (status=${githubRepo.status}, masked=${githubRepo.maskedPreview})` : 'MISSING');

  const bothPresent = githubToken && githubRepo;
  console.log(`\n=== SYNC ${bothPresent ? 'VERIFIED ✅ — both variables in ownerVariablesStore' : 'INCOMPLETE ❌'} ===`);
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

