import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const runId = `e2e-${randomUUID().slice(0, 8)}`;
  const moduleName = `backend/services/ivx-factory-e2e-final-proof-${runId}.ts`;
  const tableName = `ivx_factory_e2e_final_proof_${runId.replace(/-/g, '_')}`;
  const proofContent = `// IVX FACTORY END-TO-END LIVE PROOF — run ${runId}
// Generated ${new Date().toISOString()} by the IVX Factory Engine via Owner AI chat.
// This file is the LIVE EVIDENCE that the factory pipeline works end-to-end:
//   1. create_module  -> wrote this file on the Render container
//   2. run_supabase_migration -> created table ${tableName}
//   3. commitFactoryFilesToGitHub -> committed this file to GitHub
export const IVX_FACTORY_E2E_FINAL_PROOF_RUN_ID = '${runId}';
export const IVX_FACTORY_E2E_FINAL_PROOF_TIMESTAMP = '${new Date().toISOString()}';
export const IVX_FACTORY_E2E_FINAL_PROOF_TABLE = '${tableName}';
export const IVX_FACTORY_E2E_FINAL_PROOF_PURPOSE = 'End-to-end factory pipeline live proof: create_module + run_supabase_migration + commit-to-GitHub in one owner-approved factory job.';
`;

  const migrationSql = `CREATE TABLE IF NOT EXISTS public.${tableName} (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());`;

  const prompt = `factory: Use the IVX Factory Engine to execute a full end-to-end live proof (run ${runId}). (1) create_module: Create a new module file at path "${moduleName}" with content:\n${proofContent}\n(2) run_supabase_migration: Apply SQL migration named "${tableName}" with SQL:\n${migrationSql}\nApproval phrase: CONFIRM_IVX_FACTORY_MODE.`;

  console.log('=== IVX Factory end-to-end live proof ===');
  console.log('runId:', runId);
  console.log('module:', moduleName);
  console.log('table :', tableName);
  console.log('');

  console.log('=== Step 1: POST /api/ivx/owner-ai with factory prompt ===');
  const res = await fetch(`${API}/api/ivx/owner-ai`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_TOKEN}` },
    body: JSON.stringify({ message: prompt }),
  });
  const text = await res.text();
  console.log(`HTTP ${res.status}: ${text.slice(0, 400)}`);
  if (!res.ok) { console.error('FACTORY REQUEST FAILED'); process.exit(1); }
  const data = JSON.parse(text);
  const taskId = data?.executionStatus?.taskId || data?.taskId;
  const statusUrl = data?.executionStatus?.statusUrl;
  console.log('taskId:', taskId);
  console.log('statusUrl:', statusUrl);
  console.log('initial status:', data?.executionStatus?.status, data?.executionStatus?.stage, `${data?.executionStatus?.liveProgress ?? 0}%`);

  // Step 2: poll the worker job until terminal
  let finalJob = null;
  for (let i = 0; i < 60; i++) {
    await sleep(3000);
    if (!statusUrl) { console.log('no statusUrl — breaking poll'); break; }
    const pollRes = await fetch(`${API}${statusUrl}`, { headers: { Authorization: `Bearer ${OWNER_TOKEN}` } });
    if (!pollRes.ok) { console.log(`poll ${i} HTTP ${pollRes.status}`); continue; }
    const pollData = await pollRes.json();
    const job = pollData?.job || pollData;
    const status = job?.status;
    const stage = job?.stage;
    const progress = job?.progress ?? job?.liveProgress ?? 0;
    console.log(`poll ${i}: status=${status} stage=${stage} progress=${progress}%`);
    if (['completed', 'COMPLETED', 'failed', 'FAILED', 'blocked', 'BLOCKED', 'canceled', 'CANCELED'].includes(status)) {
      finalJob = job;
      break;
    }
  }

  console.log('\n=== Step 2: final worker job result ===');
  if (!finalJob) { console.error('NO TERMINAL JOB — timeout'); process.exit(1); }
  const result = finalJob?.result || {};
  console.log('finalStatus:', result?.finalStatus || finalJob?.stage);
  console.log('filesCreated:', JSON.stringify(result?.filesCreated || []));
  console.log('commitCreated:', result?.commitCreated);
  console.log('commitSha:', result?.commitSha);
  console.log('commitUrl:', result?.commitUrl);
  console.log('pushed:', result?.pushed);
  console.log('error:', result?.error || finalJob?.error);
  console.log('factoryCommitDiagnostics:', JSON.stringify(finalJob?.factoryCommitDiagnostics || result?.factoryCommitDiagnostics || {}));

  const commitSha = result?.commitSha || finalJob?.factoryCommitDiagnostics?.commitSha;
  if (!commitSha || commitSha === 'NONE') {
