    body: JSON.stringify({
      action: 'render_upsert_env_var',
      input: {
        serviceId: 'srv-d7t9ivreo5us73ftose0',
        key: 'IVX_OWNER_VARIABLES_ENCRYPTION_KEY',
        value: encKey,
      },
      confirm: true,
      confirmText: 'CONFIRM_IVX_RENDER_SERVICE_UPDATE',
